// Document A document associated with an estate — wills, codicils, trust deeds, and other legal documents. Extension types use the x-inherit- prefix for jurisdiction-specific or religious document types
type Document struct {
	// Clauses Structured clauses of a will or testamentary document — enables per-clause provenance tracking, succession regime tagging, and validating authority assignment
	Clauses *[]WillClause `json:"clauses,omitempty"`

	// Content Base64-encoded file content for self-contained documents. Use for small, critical files (wills, certificates, attestations) that must travel with the estate plan. For large files, use storageRef instead
	Content *[]byte `json:"content,omitempty"`

	// CreatedAt Timestamp when the document was created or executed
	CreatedAt *time.Time `json:"createdAt,omitempty"`

	// EntityId The ID of the entity this document relates to. Combined with entityType, links the document to its subject
	EntityId *openapi_types.UUID `json:"entityId,omitempty"`

	// EntityType The type of entity this document relates to. Combined with entityId, creates a contextual link: 'this PDF is the valuation certificate for asset X'
	EntityType *string `json:"entityType,omitempty"`

	// FileFormat File format or extension. Use lowercase without a leading dot
	FileFormat *string `json:"fileFormat,omitempty"`

	// FileSizeBytes File size in bytes. Zero for metadata-only entries where the document content is stored externally
	FileSizeBytes       *int                `json:"fileSizeBytes,omitempty"`
	FormalityAdmittedAt *openapi_types.Date `json:"formalityAdmittedAt,omitempty"`

	// FormalityAdmittedBy Court or authority that admitted the informal document
	FormalityAdmittedBy *string `json:"formalityAdmittedBy,omitempty"`

	// FormalityJurisdiction A legal jurisdiction identified by ISO 3166 codes. Succession law varies not just by country but by subdivision — Scotland differs from England and Wales, and US states have radically different rules
	FormalityJurisdiction *Jurisdiction `json:"formalityJurisdiction,omitempty"`

	// FormalityNotes Circumstances of informal execution
	FormalityNotes *string `json:"formalityNotes,omitempty"`

	// FormalityStatus Whether the document meets strict formalities or was admitted under a curative/dispensing power
	FormalityStatus interface{} `json:"formalityStatus,omitempty"`

	// Id Unique identifier for this document within the INHERIT document
	Id openapi_types.UUID `json:"id"`

	// Images Scans or photographs of this document — useful when the original is a physical paper document
	Images *[]Media `json:"images,omitempty"`

	// MimeType MIME type of the document file
	MimeType *string `json:"mimeType,omitempty"`

	// Notes Free-text notes about this document. Use for provenance, authenticity concerns, or handling instructions
	Notes *string `json:"notes,omitempty"`

	// Provenance Consolidated provenance metadata for any entity — replaces the 5-7 scattered provenance fields that were previously repeated on every entity. Tracks how the data was created, by whom, and whether a human has verified it
	Provenance *Provenance `json:"provenance,omitempty"`

	// Registrations Registries where this document has been registered. Tracks will registration with services such as the National Will Register (England & Wales) or the Register of Deeds (Scotland). Maps to Schema.org RegisterAction
	Registrations *[]struct {
		// Jurisdiction A legal jurisdiction identified by ISO 3166 codes. Succession law varies not just by country but by subdivision — Scotland differs from England and Wales, and US states have radically different rules
		Jurisdiction *Jurisdiction `json:"jurisdiction,omitempty"`

		// Reference Registration reference number
		Reference *string `json:"reference,omitempty"`

		// RegisteredAt Date of registration
		RegisteredAt openapi_types.Date `json:"registeredAt"`

		// Registry Name of the registry
		Registry string `json:"registry"`

		// RegistryUrl URL of the registry for verification
		RegistryUrl *string `json:"registryUrl,omitempty"`

		// VerifiedAt When the registration was last verified as current
		VerifiedAt *time.Time `json:"verifiedAt,omitempty"`
	} `json:"registrations,omitempty"`

	// RegistryReference Structured reference to a government registry entry
	RegistryReference *struct {
		ReferenceNumber *string             `json:"referenceNumber,omitempty"`
		RegisteredAt    *openapi_types.Date `json:"registeredAt,omitempty"`

		// RegistryJurisdiction A legal jurisdiction identified by ISO 3166 codes. Succession law varies not just by country but by subdivision — Scotland differs from England and Wales, and US states have radically different rules
		RegistryJurisdiction *Jurisdiction `json:"registryJurisdiction,omitempty"`

		// RegistryName e.g. Legal Affairs Bureau, FCDDV, HMCTS Probate Registry
		RegistryName           string              `json:"registryName"`
		RegistryOrganisationId *openapi_types.UUID `json:"registryOrganisationId,omitempty"`

		// RegistryOrganisationIdDisplay Human-readable display name for the referenced registry organisation
		RegistryOrganisationIdDisplay *string     `json:"registryOrganisationIdDisplay,omitempty"`
		RegistryType                  interface{} `json:"registryType,omitempty"`
		VerificationUrl               *string     `json:"verificationUrl,omitempty"`
	} `json:"registryReference,omitempty"`

	// StorageRef Storage reference — an S3 URI, file path, external system reference, or document management system identifier
	StorageRef *string `json:"storageRef,omitempty"`

	// Title Human-readable title of the document
	Title string `json:"title"`

	// Type The type of document. Core types cover common law and civil law documents. Extension types use the x-inherit- prefix
	Type Document_Type `json:"type"`
}

